<script setup>import{inject}from'vue';const s=inject('planAdmin');const label=v=>v.split('.').map(x=>x.charAt(0).toUpperCase()+x.slice(1)).join(' ');const date=v=>new Intl.DateTimeFormat(undefined,{dateStyle:'medium',timeStyle:'short'}).format(new Date(v));</script><template><section class="admin-card"><div class="card-heading"><h2>Plan activity</h2></div><div class="table-wrap"><table><thead><tr><th>Action</th><th>Description</th><th>Actor</th><th>Date / Time</th></tr></thead><tbody><tr v-for="item in s.activity.value" :key="item.id"><td class="font-semibold">{{label(item.action)}}</td><td>{{item.metadata?.changed?.length?'Changed: '+item.metadata.changed.join(', '):'Plan created'}}</td><td>{{item.actor_name||'System'}}</td><td>{{date(item.created_at)}}</td></tr></tbody></table><p v-if="!s.activity.value.length" class="empty-state">No plan activity recorded.</p></div></section></template>
